// Package store is ResticGUI's SQLite storage: versioned migrations (goose)
// and typed queries generated by sqlc into the db subpackage.
//
// Regenerate the queries after changing migrations/ or queries/ with:
//
//	sqlc generate -f internal/store/sqlc.yaml
package store

import (
	"context"
	"database/sql"
	"embed"
	"encoding/json"
	"fmt"
	"io/fs"
	"net/url"

	"github.com/pressly/goose/v3"
	_ "modernc.org/sqlite" // registers the "sqlite" driver, pure Go

	"github.com/mathieuHa/resticgui/internal/secrets"
	"github.com/mathieuHa/resticgui/internal/store/db"
)

//go:embed migrations/*.sql
var embedded embed.FS

// Store wraps the database handle and the generated queries.
type Store struct {
	*db.Queries
	DB *sql.DB
}

// Open opens (or creates) the database at path and applies pending migrations.
func Open(ctx context.Context, path string) (*Store, error) {
	conn, err := sql.Open("sqlite", dsn(path))
	if err != nil {
		return nil, err
	}
	// SQLite allows a single writer; one connection avoids SQLITE_BUSY between
	// our own goroutines and keeps every query on the same pragmas.
	conn.SetMaxOpenConns(1)

	if err := migrate(ctx, conn); err != nil {
		conn.Close()
		return nil, err
	}
	return &Store{Queries: db.New(conn), DB: conn}, nil
}

func dsn(path string) string {
	q := url.Values{}
	q.Add("_pragma", "foreign_keys(1)")
	q.Add("_pragma", "busy_timeout(5000)")
	q.Add("_pragma", "journal_mode(WAL)")
	return "file:" + path + "?" + q.Encode()
}

func newMigrator(conn *sql.DB) (*goose.Provider, error) {
	migrations, err := fs.Sub(embedded, "migrations")
	if err != nil {
		return nil, err
	}
	return goose.NewProvider(goose.DialectSQLite3, conn, migrations)
}

func migrate(ctx context.Context, conn *sql.DB) error {
	migrator, err := newMigrator(conn)
	if err != nil {
		return err
	}
	if _, err := migrator.Up(ctx); err != nil {
		return fmt.Errorf("store: migrate: %w", err)
	}
	return nil
}

// Close closes the database.
func (s *Store) Close() error {
	return s.DB.Close()
}

// InTx runs fn in a transaction, committing when it returns nil.
func (s *Store) InTx(ctx context.Context, fn func(q *db.Queries) error) error {
	tx, err := s.DB.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	if err := fn(s.Queries.WithTx(tx)); err != nil {
		_ = tx.Rollback()
		return err
	}
	return tx.Commit()
}

// RepositorySecrets is the encrypted part of a repository: its restic
// password and the backend credentials passed to restic as environment
// variables (AWS_SECRET_ACCESS_KEY, B2_ACCOUNT_KEY, ...).
type RepositorySecrets struct {
	Password string            `json:"password"`
	Env      map[string]string `json:"env,omitempty"`
}

// SealSecrets encrypts s for the repositories.secrets column.
func SealSecrets(box *secrets.Box, s RepositorySecrets) ([]byte, error) {
	plaintext, err := json.Marshal(s)
	if err != nil {
		return nil, err
	}
	return box.Seal(plaintext)
}

// OpenSecrets decrypts the repositories.secrets column.
func OpenSecrets(box *secrets.Box, sealed []byte) (RepositorySecrets, error) {
	var s RepositorySecrets
	plaintext, err := box.Open(sealed)
	if err != nil {
		return s, err
	}
	err = json.Unmarshal(plaintext, &s)
	return s, err
}

// RepositoryOptions is the non-secret configuration stored as JSON in
// repositories.options.
type RepositoryOptions struct {
	// Env holds non-secret environment variables, such as AWS_DEFAULT_REGION.
	Env map[string]string `json:"env,omitempty"`
	// CACert is a path passed to restic --cacert.
	CACert string `json:"cacert,omitempty"`
	// Extended holds restic -o key=value options, such as s3.storage-class.
	Extended map[string]string `json:"extended,omitempty"`
}

// EncodeOptions returns o as the JSON stored in repositories.options.
func EncodeOptions(o RepositoryOptions) (string, error) {
	b, err := json.Marshal(o)
	return string(b), err
}

// DecodeOptions parses repositories.options.
func DecodeOptions(s string) (RepositoryOptions, error) {
	var o RepositoryOptions
	err := json.Unmarshal([]byte(s), &o)
	return o, err
}
